"""Runs every module on one piece of evidence and fans events out to listeners."""

import asyncio
import hashlib
import json
import os
import shutil
import time
import traceback
import uuid
from typing import Any

import psycopg

from earwitness import db
from earwitness.modules import registry
from earwitness.modules.base import CaseContext
from earwitness.modules.base import Reporter
from earwitness.modules.base import Skip
from earwitness.modules.base import run_tool


class Case:
    def __init__(
        self, case_id: str, workdir: str, filename: str, options: dict[str, Any]
    ):
        self.id = case_id
        self.workdir = workdir
        self.filename = filename
        self.options = options
        self.created = time.time()
        self.events: list[dict[str, Any]] = []
        self.listeners: set[asyncio.Queue[dict[str, Any]]] = set()
        self.status = "queued"
        self.ctx: CaseContext | None = None
        self.task: asyncio.Task[None] | None = None
        self._log = None

    @property
    def evidence_path(self) -> str:
        return os.path.join(
            self.workdir, "evidence" + os.path.splitext(self.filename)[1].lower()
        )

    def emit(self, event: dict[str, Any]) -> None:
        event = {"seq": len(self.events), "ts": round(time.time(), 3), **event}
        self.events.append(event)

        if self._log is None:
            self._log = open(os.path.join(self.workdir, "events.jsonl"), "a")

        self._log.write(json.dumps(event) + "\n")
        self._log.flush()

        for queue in list(self.listeners):
            queue.put_nowait(event)

    def summary(self) -> dict[str, Any]:
        case_event = next((e for e in self.events if e["type"] == "case"), None)
        findings = [e["finding"] for e in self.events if e["type"] == "finding"]
        brief = next(
            (
                e["artifact"]["data"]
                for e in reversed(self.events)
                if e["type"] == "artifact" and e["artifact"]["id"] == "brief:brief"
            ),
            {},
        )

        return {
            "id": self.id,
            "filename": self.filename,
            "created": self.created,
            "status": self.status,
            "findings": len(findings),
            "warnings": sum(f["severity"] in ("warning", "critical") for f in findings),
            "case": case_event["case"] if case_event else None,
            "verdict": brief.get("verdict"),
            "summary_plain": brief.get("summary_plain"),
        }


class CaseStore:
    def __init__(self, root: str):
        self.root = root
        self.cases: dict[str, Case] = {}
        os.makedirs(root, exist_ok=True)
        self._load_existing()

    def _load_existing(self) -> None:
        for case_id in sorted(os.listdir(self.root)):
            workdir = os.path.join(self.root, case_id)
            meta_path = os.path.join(workdir, "case.json")

            if not os.path.isfile(meta_path):
                continue

            with open(meta_path) as handle:
                meta = json.load(handle)

            case = Case(case_id, workdir, meta["filename"], meta.get("options", {}))
            case.created = meta.get("created", case.created)
            events_path = os.path.join(workdir, "events.jsonl")

            if os.path.isfile(events_path):
                with open(events_path) as handle:
                    case.events = [json.loads(line) for line in handle if line.strip()]

            done = any(e["type"] == "done" for e in case.events)
            case.status = "done" if done else "interrupted"
            self.cases[case_id] = case

    def create(self, filename: str, options: dict[str, Any] | None = None) -> Case:
        case_id = time.strftime("%Y%m%d-%H%M%S-") + uuid.uuid4().hex[:6]
        workdir = os.path.join(self.root, case_id)
        os.makedirs(workdir)
        case = Case(case_id, workdir, os.path.basename(filename), options or {})

        with open(os.path.join(workdir, "case.json"), "w") as handle:
            json.dump(
                {
                    "filename": case.filename,
                    "created": case.created,
                    "options": case.options,
                },
                handle,
            )

        self.cases[case_id] = case

        return case

    def delete(self, case_id: str) -> bool:
        case = self.cases.pop(case_id, None)

        if case is None:
            return False

        if case.task and not case.task.done():
            case.task.cancel()

        shutil.rmtree(case.workdir, ignore_errors=True)

        return True

    async def sync_index(self) -> None:
        """Backfill the database index with every case on disk."""
        for case in list(self.cases.values()):
            await db.index_case(case)

    def start(self, case: Case, *, only: list[str] | None = None) -> None:
        case.task = asyncio.create_task(run_case(case, only=only))


async def _make_proxy(case: Case) -> str | None:
    """An H.264 copy every browser can play (phones record HEVC/VP9)."""
    out = os.path.join(case.workdir, "proxy.mp4")

    if os.path.isfile(out):
        return out

    result = await run_tool(
        "ffmpeg", "-nostdin", "-v", "error", "-y", "-i", case.evidence_path,
        "-map", "0:v:0?", "-map", "0:a:0?",
        "-vf", "scale='min(1280,iw)':-2",
        "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-pix_fmt", "yuv420p",
        "-c:a", "aac", "-b:a", "128k", "-movflags", "+faststart", out,
    )  # fmt: skip

    return out if result is not None and os.path.isfile(out) else None


async def _thumbnail(case: Case) -> None:
    await run_tool(
        "ffmpeg", "-nostdin", "-v", "error", "-y", "-ss", "0.5", "-i", case.evidence_path,
        "-frames:v", "1", "-vf", "scale=320:-2,format=yuvj420p", os.path.join(case.workdir, "thumb.jpg"),
    )  # fmt: skip


def _hash_file(path: str) -> tuple[str, str]:
    sha, md5 = hashlib.sha256(), hashlib.md5()

    with open(path, "rb") as handle:
        while chunk := handle.read(1 << 20):
            sha.update(chunk)
            md5.update(chunk)

    return sha.hexdigest(), md5.hexdigest()


def _fps(text: str | None) -> float | None:
    if not text or text in ("0/0", "N/A"):
        return None

    num, _, den = text.partition("/")

    return round(float(num) / float(den), 3) if den and float(den) else float(num)


def _num(value: Any) -> float | None:
    try:
        return float(value)
    except TypeError, ValueError:
        return None


async def _custody(case: "Case", probe: dict[str, Any]) -> dict[str, Any]:
    """Chain-of-custody facts: hashes, container, every stream, every tag."""
    sha256, md5 = await asyncio.to_thread(_hash_file, case.evidence_path)
    fmt = probe.get("format", {})
    tags: dict[str, str] = {}

    for key, value in fmt.get("tags", {}).items():
        tags[key] = str(value)

    for stream in probe.get("streams", []):
        for key, value in stream.get("tags", {}).items():
            tags.setdefault(f"stream{stream.get('index')}.{key}", str(value))

    streams = [
        {
            "index": s.get("index"),
            "type": s.get("codec_type"),
            "codec": s.get("codec_name"),
            "codec_long": s.get("codec_long_name"),
            "profile": s.get("profile"),
            "width": s.get("width"),
            "height": s.get("height"),
            "fps": _fps(s.get("avg_frame_rate"))
            if s.get("codec_type") == "video"
            else None,
            "pix_fmt": s.get("pix_fmt"),
            "color_range": s.get("color_range"),
            "color_space": s.get("color_space"),
            "bit_rate": _num(s.get("bit_rate")),
            "sample_rate": _num(s.get("sample_rate")),
            "channels": s.get("channels"),
            "channel_layout": s.get("channel_layout"),
            "language": s.get("tags", {}).get("language"),
            "handler": s.get("tags", {}).get("handler_name"),
            "duration_s": _num(s.get("duration")),
            "frames": _num(s.get("nb_frames")),
        }
        for s in probe.get("streams", [])
    ]

    return {
        "sha256": sha256,
        "md5": md5,
        "ingested_at": case.created,
        "container": {
            "format_name": fmt.get("format_name"),
            "format_long_name": fmt.get("format_long_name"),
            "bit_rate": _num(fmt.get("bit_rate")),
            "size_bytes": _num(fmt.get("size")),
            "duration_s": _num(fmt.get("duration")),
        },
        "streams": streams,
        "tags": tags,
    }


async def _index(case: Case) -> None:
    # The files are the record of the run; a database hiccup must not sink it.
    try:
        await db.index_case(case)
    except (psycopg.Error, OSError) as error:
        case.emit(
            {"type": "log", "module": "index",
             "message": f"database index not updated: {type(error).__name__}: {error}"}
        )  # fmt: skip


async def run_case(case: Case, *, only: list[str] | None = None) -> None:
    case.status = "running"
    # Mark the case running in the index without holding up the analysis.
    started_index = asyncio.create_task(_index(case))
    ctx = CaseContext(case.id, case.evidence_path, case.workdir, case.options)
    case.ctx = ctx
    probe = await ctx.probe()
    info = await ctx.video_info()
    has_audio = any(s.get("codec_type") == "audio" for s in probe.get("streams", []))
    modules = [m for m in registry.all_modules() if only is None or m.name in only]

    # Modules not scheduled in this run count as finished with nothing to say,
    # so anything waiting on them carries on immediately.
    for other in registry.all_modules():
        if other.name not in {m.name for m in modules}:
            ctx.publish(other.name, None)
    proxy_task = asyncio.create_task(_make_proxy(case))
    await _thumbnail(case)
    case.emit(
        {
            "type": "case",
            "case": {
                "id": case.id,
                "filename": case.filename,
                "duration_s": float(probe.get("format", {}).get("duration") or 0),
                "size_bytes": int(probe.get("format", {}).get("size") or 0),
                "has_audio": has_audio,
                "video": None
                if info is None
                else {
                    "width": info.width,
                    "height": info.height,
                    "fps": round(info.fps, 3),
                    "codec": info.codec,
                    "frames": info.frame_count,
                },
                "thumb_url": f"/api/cases/{case.id}/files/thumb.jpg",
                "media_url": None,
                **(await _custody(case, probe)),
                "modules": [
                    {"name": m.name, "title": m.title, "description": m.description}
                    for m in modules
                ],
            },
        }
    )

    for module in modules:
        case.emit(
            {"type": "module", "module": module.name, "status": "queued", "progress": 0}
        )

    # Heavy modules are numpy/OpenCV bound; a small limit keeps the UI lively.
    gate = asyncio.Semaphore(int(os.environ.get("EARWITNESS_PARALLEL", "4")))

    async def one(module: Any) -> None:
        reporter = Reporter(module.name, ctx, case.emit)
        depends = list(getattr(module, "depends", ()))

        if depends == ["*"]:
            depends = [m.name for m in modules if m.name != module.name]

        if depends:
            case.emit(
                {"type": "module", "module": module.name, "status": "waiting",
                 "progress": 0, "message": "waiting for " + ", ".join(depends)}
            )  # fmt: skip

        for dependency in depends:
            if any(m.name == dependency for m in modules):
                await ctx.wait_for(dependency)

        started = time.time()

        async with gate:
            case.emit(
                {
                    "type": "module",
                    "module": module.name,
                    "status": "running",
                    "progress": 0,
                }
            )

            try:
                await module.run(ctx, reporter)
            except Skip as reason:
                ctx.publish(module.name, None)
                case.emit(
                    {"type": "module", "module": module.name, "status": "skipped",
                     "progress": 1, "message": str(reason)}
                )  # fmt: skip

                return
            except asyncio.CancelledError:
                raise
            except Exception as error:  # noqa: BLE001 - one module must not sink the case
                ctx.publish(module.name, None)
                case.emit(
                    {"type": "module", "module": module.name, "status": "error",
                     "progress": 1, "message": f"{type(error).__name__}: {error}",
                     "trace": traceback.format_exc()[-2000:]}
                )  # fmt: skip

                return

        if module.name not in ctx._published:
            ctx.publish(module.name, None)

        case.emit(
            {"type": "module", "module": module.name, "status": "done", "progress": 1,
             "elapsed_s": round(time.time() - started, 2)}
        )  # fmt: skip

    async def proxy() -> None:
        path = await proxy_task
        case.emit(
            {
                "type": "media",
                "media_url": f"/api/cases/{case.id}/files/proxy.mp4" if path else None,
            }
        )

    await asyncio.gather(proxy(), *(one(m) for m in modules))
    case.status = "done"
    await started_index
    await _index(case)
    case.emit({"type": "done"})

"""HTTP + WebSocket front door for the forensic suite."""

import asyncio
import os
import shutil
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from datetime import datetime
from datetime import timezone
from typing import Any

from fastapi import FastAPI
from fastapi import HTTPException
from fastapi import UploadFile
from fastapi import WebSocket
from fastapi import WebSocketDisconnect
from fastapi.responses import FileResponse
from fastapi.responses import HTMLResponse
from fastapi.responses import JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

from earwitness import db
from earwitness.modules import registry
from earwitness.server import enhance
from earwitness.server import report_html
from earwitness.server.jobs import CaseStore

_ROOT = os.path.dirname(
    os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
)
_WEB = os.path.join(_ROOT, "web", "dist")

# earwitness.db has loaded .env by now.
store = CaseStore(os.environ.get("EARWITNESS_CASES", os.path.join(_ROOT, "cases")))


@asynccontextmanager
async def _lifespan(_: FastAPI) -> AsyncIterator[None]:
    # The database is required: fail at startup, not on the first case.
    db.url()
    await db.migrate()
    await db.open_pool()
    await store.sync_index()

    try:
        yield
    finally:
        await db.close_pool()


app = FastAPI(title="earwitness", lifespan=_lifespan)


def _when(text: str | None, name: str) -> datetime | None:
    if not text:
        return None

    try:
        moment = datetime.fromisoformat(text)
    except ValueError:
        raise HTTPException(400, f"{name} must be an ISO date/time")

    return moment if moment.tzinfo else moment.replace(tzinfo=timezone.utc)


class PathCase(BaseModel):
    path: str
    options: dict[str, Any] = {}


class EnhanceRequest(BaseModel):
    time_s: float
    x: float
    y: float
    w: float
    h: float
    frames: int = 9


def _case(case_id: str):
    case = store.cases.get(case_id)

    if case is None:
        raise HTTPException(404, "no such case")

    return case


@app.get("/api/health")
async def health() -> dict[str, Any]:
    return {
        "ok": True,
        "openai": bool(os.environ.get("OPENAI_API_KEY")),
        "database": await db.health(),
        "modules": [
            {"name": m.name, "title": m.title, "description": m.description}
            for m in registry.all_modules()
        ],
    }


@app.get("/api/cases")
async def list_cases() -> list[dict[str, Any]]:
    return sorted(
        (c.summary() for c in store.cases.values()), key=lambda s: -s["created"]
    )


@app.post("/api/cases")
async def upload(
    file: UploadFile, approx_time: str | None = None, search_hours: float | None = None
) -> dict[str, Any]:
    options: dict[str, Any] = {"original_name": file.filename}

    if approx_time:
        options["approx_time"] = approx_time

    if search_hours:
        options["search_hours"] = search_hours

    case = store.create(file.filename or "evidence.mp4", options)

    with open(case.evidence_path, "wb") as handle:
        await asyncio.to_thread(shutil.copyfileobj, file.file, handle, 1 << 20)

    store.start(case)

    return case.summary()


@app.post("/api/cases/from-path")
async def from_path(request: PathCase) -> dict[str, Any]:
    """Open a file already on this machine (no upload; handy for big files)."""
    path = os.path.expanduser(request.path)

    if not os.path.isfile(path):
        raise HTTPException(400, "file not found")

    options = {"original_name": os.path.basename(path), **request.options}
    # A grid record saved next to the evidence is used automatically.
    sibling = os.path.join(os.path.dirname(path), "grid.csv")

    if "grid_path" not in options and os.path.isfile(sibling):
        options["grid_path"] = sibling

    case = store.create(path, options)
    await asyncio.to_thread(shutil.copyfile, path, case.evidence_path)
    store.start(case)

    return case.summary()


@app.get("/api/cases/{case_id}")
async def get_case(case_id: str) -> dict[str, Any]:
    case = _case(case_id)

    return {"summary": case.summary(), "events": case.events}


@app.delete("/api/cases/{case_id}")
async def delete_case(case_id: str) -> dict[str, Any]:
    deleted = store.delete(case_id)
    await db.delete_case(case_id)

    return {"deleted": deleted}


@app.get("/api/search")
async def search(
    since: str | None = None,
    until: str | None = None,
    severity: str | None = None,
    module: str | None = None,
    q: str | None = None,
    limit: int = 200,
) -> list[dict[str, Any]]:
    """Findings across every case, newest first."""
    rows = await db.search_findings(
        since=_when(since, "since"),
        until=_when(until, "until"),
        severity=severity,
        module=module,
        text=q,
        limit=max(1, min(limit, 1000)),
    )

    return db.to_json(rows)


@app.get("/api/search/dated")
async def search_dated(
    start: str | None = None, end: str | None = None
) -> list[dict[str, Any]]:
    """Cases the grid record dated into [start, end]."""
    return db.to_json(
        await db.search_cases(
            dated_from=_when(start, "start"), dated_to=_when(end, "end")
        )
    )


@app.get("/api/grid")
async def grid_minutes(start: str, end: str) -> list[dict[str, Any]]:
    """Stored GB grid frequency as one-minute buckets (continuous aggregate)."""
    lo, hi = _when(start, "start"), _when(end, "end")

    if lo is None or hi is None or hi <= lo or (hi - lo).days > 31:
        raise HTTPException(400, "need start < end, at most 31 days apart")

    return db.to_json(await db.grid_minutes(lo, hi))


@app.post("/api/cases/{case_id}/rerun")
async def rerun(case_id: str, modules: list[str] | None = None) -> dict[str, Any]:
    case = _case(case_id)

    if case.task and not case.task.done():
        raise HTTPException(409, "already running")

    case.events.clear()

    for queue in list(case.listeners):
        queue.put_nowait({"type": "reset", "seq": -1})

    events = os.path.join(case.workdir, "events.jsonl")

    if os.path.isfile(events):
        os.remove(events)

    case._log = None
    case.status = "queued"
    store.start(case, only=modules)

    return case.summary()


@app.get("/api/cases/{case_id}/files/{path:path}")
async def case_file(case_id: str, path: str) -> FileResponse:
    case = _case(case_id)
    full = os.path.realpath(os.path.join(case.workdir, path))

    if not full.startswith(
        os.path.realpath(case.workdir) + os.sep
    ) or not os.path.isfile(full):
        raise HTTPException(404, "no such file")

    return FileResponse(full)


@app.post("/api/cases/{case_id}/enhance")
async def enhance_region(case_id: str, request: EnhanceRequest) -> JSONResponse:
    case = _case(case_id)
    result = await enhance.enhance(
        case,
        request.time_s,
        (request.x, request.y, request.w, request.h),
        request.frames,
    )

    if result is None:
        raise HTTPException(422, "could not enhance this region")

    return JSONResponse(result)


@app.get("/api/cases/{case_id}/report", response_class=HTMLResponse)
async def report(case_id: str) -> HTMLResponse:
    return HTMLResponse(report_html.render(_case(case_id)))


@app.websocket("/ws/cases/{case_id}")
async def stream(socket: WebSocket, case_id: str) -> None:
    case = store.cases.get(case_id)
    await socket.accept()

    if case is None:
        await socket.send_json({"type": "error", "message": "no such case"})
        await socket.close()

        return

    queue: asyncio.Queue[dict[str, Any]] = asyncio.Queue()
    # Register before replaying so no event falls between the two.
    case.listeners.add(queue)

    try:
        replay = list(case.events)

        for event in replay:
            await socket.send_json(event)

        seen = len(replay)

        while True:
            event = await queue.get()

            if event["type"] == "reset":
                seen = 0
                await socket.send_json(event)

                continue

            if event["seq"] < seen:
                continue

            await socket.send_json(event)
    except WebSocketDisconnect:
        pass
    finally:
        case.listeners.discard(queue)


if os.path.isdir(_WEB):
    app.mount(
        "/assets", StaticFiles(directory=os.path.join(_WEB, "assets")), name="assets"
    )

    @app.get("/{path:path}")
    async def spa(path: str) -> FileResponse:
        candidate = os.path.join(_WEB, path)

        if path and os.path.isfile(candidate):
            return FileResponse(candidate)

        return FileResponse(os.path.join(_WEB, "index.html"))

"""What an analyst would notice in the frames (OpenAI vision, optional).

Keyframes go to a vision model with a strict JSON schema: setting, likely
region and its visual evidence, time of day, notable observations, and any
visual signs of manipulation. Everything it says is labelled AI-inferred.
"""

import base64

import cv2
import numpy as np

from earwitness import openai_client
from earwitness.modules.base import CaseContext
from earwitness.modules.base import Reporter
from earwitness.modules.base import Skip

_FRAMES = 6

_SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "required": [
        "scene",
        "setting",
        "location",
        "time_of_day",
        "weather",
        "observations",
        "manipulation_signs",
    ],
    "properties": {
        "scene": {
            "type": "string",
            "description": "One or two sentences: what the footage shows.",
        },
        "setting": {
            "type": "string",
            "enum": ["indoor", "outdoor", "vehicle", "mixed", "unknown"],
        },
        "location": {
            "type": "object",
            "additionalProperties": False,
            "required": [
                "guess",
                "confidence",
                "evidence",
                "latitude",
                "longitude",
                "radius_km",
            ],
            "properties": {
                "latitude": {
                    "type": "number",
                    "description": "Best-estimate latitude (0 if unknown).",
                },
                "longitude": {
                    "type": "number",
                    "description": "Best-estimate longitude (0 if unknown).",
                },
                "radius_km": {
                    "type": "number",
                    "description": "Honest ~80% radius; 20000 if the place is unknown.",
                },
                "guess": {
                    "type": "string",
                    "description": "Most specific defensible place (country/city/venue), or 'unknown'.",
                },
                "confidence": {"type": "string", "enum": ["low", "medium", "high"]},
                "evidence": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Visual clues: signage language, plugs, plates, architecture, vegetation, road markings…",
                },
            },
        },
        "time_of_day": {
            "type": "object",
            "additionalProperties": False,
            "required": ["guess", "evidence"],
            "properties": {"guess": {"type": "string"}, "evidence": {"type": "string"}},
        },
        "weather": {"type": "string"},
        "observations": {
            "type": "array",
            "maxItems": 8,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "required": ["frame", "category", "description", "significance"],
                "properties": {
                    "frame": {"type": "integer"},
                    "category": {
                        "type": "string",
                        "enum": [
                            "text",
                            "landmark",
                            "vehicle",
                            "person",
                            "object",
                            "screen",
                            "reflection",
                            "anomaly",
                        ],
                    },
                    "description": {"type": "string"},
                    "significance": {
                        "type": "string",
                        "description": "Why an investigator would care.",
                    },
                },
            },
        },
        "manipulation_signs": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": False,
                "required": ["frame", "description"],
                "properties": {
                    "frame": {"type": "integer"},
                    "description": {"type": "string"},
                },
            },
        },
    },
}

_INSTRUCTIONS = (
    "You are a careful open-source-intelligence and video forensics analyst. You receive numbered "
    "keyframes from one video. Report only what is visible; never invent text you cannot read. Prefer "
    "'unknown' over guessing. Location clues: signage language and fonts, plug sockets, licence plates, "
    "road markings and driving side, architecture, vegetation, shop brands, weather and sun. Look for "
    "reflections (windows, glasses, screens) that reveal what is off-camera. Note manipulation signs only "
    "if concrete (warped background near a face, inconsistent shadows, mismatched lighting, cloned "
    "texture, impossible geometry)."
)


class Vision:
    name = "vision"
    title = "AI VISUAL ANALYST"
    description = "Keyframes read by a vision model: place, time of day, notable details, manipulation signs (optional)."
    depends = ["timeline"]

    async def run(self, ctx: CaseContext, out: Reporter) -> None:
        if not openai_client.enabled():
            raise Skip("set OPENAI_API_KEY to enable")

        info = await ctx.video_info()

        if info is None:
            raise Skip("no video stream")

        timeline = await ctx.wait_for("timeline") or {}
        times = list(np.linspace(0.3, max(0.3, info.duration_s - 0.3), _FRAMES))

        for cut in (timeline.get("cuts") or [])[:3]:
            times.append(cut + 0.3)

        times = sorted({round(t, 2) for t in times})[: _FRAMES + 2]
        content = [
            {
                "type": "input_text",
                "text": f"{len(times)} keyframes follow, numbered from 1 in time order.",
            }
        ]
        out.progress(0.1, "grabbing keyframes")

        for number, time_s in enumerate(times, start=1):
            frame = await ctx.frame_at(time_s, width=min(1024, info.width))

            if frame is None:
                continue

            _, jpeg = cv2.imencode(
                ".jpg",
                cv2.cvtColor(frame, cv2.COLOR_RGB2BGR),
                [cv2.IMWRITE_JPEG_QUALITY, 82],
            )
            content.append(
                {"type": "input_text", "text": f"Frame {number} at {time_s:.1f} s:"}
            )
            content.append(
                {
                    "type": "input_image",
                    "image_url": "data:image/jpeg;base64,"
                    + base64.b64encode(jpeg.tobytes()).decode(),
                }
            )

        out.progress(0.3, "consulting vision model")
        result = await openai_client.structured(
            ctx.workdir,
            instructions=_INSTRUCTIONS,
            content=content,
            schema=_SCHEMA,
            name="visual_report",
        )
        frame_time = {i: t for i, t in enumerate(times, start=1)}
        model = result.get("_model", "model")
        out.artifact(
            "report",
            "text",
            f"Visual analyst ({model})",
            data={"text": result["scene"]},
        )
        out.finding(
            "info",
            f"Scene: {result['setting']}",
            result["scene"]
            + (
                f" Weather: {result['weather']}."
                if result.get("weather") and result["weather"].lower() != "unknown"
                else ""
            ),
            kind="inferred",
            tags=["scene"],
        )
        location = result["location"]

        if location["guess"].lower() != "unknown":
            out.finding(
                "notice",
                f"Looks like: {location['guess']} ({location['confidence']} confidence)",
                "Visual clues: " + "; ".join(location["evidence"][:6]) + ".",
                kind="inferred",
                tags=["location"],
                data=location,
            )

        if result["time_of_day"]["guess"].lower() != "unknown":
            out.finding(
                "info",
                f"Time of day: {result['time_of_day']['guess']}",
                result["time_of_day"]["evidence"],
                kind="inferred",
                tags=["time"],
            )

        for item in result["observations"][:5]:
            out.finding(
                "info",
                f"{item['category'].capitalize()}: {item['description'][:80]}",
                f"{item['description']} {item['significance']}",
                time_s=frame_time.get(item["frame"]),
                kind="inferred",
                tags=["observation", item["category"]],
            )

        for sign in result["manipulation_signs"][:5]:
            out.finding(
                "warning",
                "Possible visual manipulation",
                sign["description"],
                time_s=frame_time.get(sign["frame"]),
                kind="inferred",
                tags=["tamper"],
            )

        ctx.publish(self.name, result)
        out.progress(1.0)

"""Thin OpenAI wrapper: key from the environment only, per-case caching, model fallback."""

import hashlib
import json
import os
from typing import Any

_VISION_MODELS = [
    m
    for m in [
        os.environ.get("EARWITNESS_OPENAI_MODEL"),
        "gpt-5.5",
        "gpt-5.4",
        "gpt-5",
        "gpt-4.1",
    ]
    if m
]
_working_model: str | None = None


def enabled() -> bool:
    return bool(os.environ.get("OPENAI_API_KEY"))


def _client():
    from openai import AsyncOpenAI

    return AsyncOpenAI()


def _cache(workdir: str, key: str) -> str:
    directory = os.path.join(workdir, "openai-cache")
    os.makedirs(directory, exist_ok=True)

    return os.path.join(
        directory, hashlib.sha1(key.encode()).hexdigest()[:20] + ".json"
    )


async def structured(
    workdir: str,
    *,
    instructions: str,
    content: list[dict[str, Any]],
    schema: dict[str, Any],
    name: str,
    effort: str | None = None,
) -> dict[str, Any]:
    """JSON-schema-constrained response from the first model that works."""
    global _working_model
    from openai import APIStatusError
    from openai import NotFoundError

    key = json.dumps(
        [instructions, content, schema, effort], sort_keys=True, default=str
    )
    path = _cache(workdir, key)

    if os.path.isfile(path):
        with open(path) as handle:
            return json.load(handle)

    client = _client()
    models = [_working_model] if _working_model else _VISION_MODELS
    last_error: Exception | None = None

    for model in models:
        try:
            extra = {"reasoning": {"effort": effort}} if effort else {}
            response = await client.responses.create(
                **extra,
                model=model,
                instructions=instructions,
                input=[{"role": "user", "content": content}],
                text={
                    "format": {
                        "type": "json_schema",
                        "name": name,
                        "schema": schema,
                        "strict": True,
                    }
                },
            )
        except (NotFoundError, APIStatusError) as error:
            # Unknown model or no access: try the next one. Auth/quota errors repeat for all.
            last_error = error
            status = getattr(error, "status_code", None)

            if status in (401, 429):
                raise

            continue

        _working_model = model
        result = json.loads(response.output_text)
        result["_model"] = model

        with open(path, "w") as handle:
            json.dump(result, handle)

        return result

    raise RuntimeError(f"no OpenAI model available: {last_error}")


async def transcribe(
    workdir: str, audio_path: str, model: str = "whisper-1"
) -> dict[str, Any]:
    """Speech to text. whisper-1 gives timed segments and a language guess;
    newer models (gpt-4o-transcribe) give text only."""
    with open(audio_path, "rb") as handle:
        digest = hashlib.sha1(handle.read()).hexdigest()

    path = _cache(workdir, f"transcribe:{model}:" + digest)

    if os.path.isfile(path):
        with open(path) as handle:
            return json.load(handle)

    client = _client()

    with open(audio_path, "rb") as handle:
        if model == "whisper-1":
            response = await client.audio.transcriptions.create(
                model=model,
                file=handle,
                response_format="verbose_json",
                timestamp_granularities=["segment"],
            )
        else:
            response = await client.audio.transcriptions.create(
                model=model, file=handle
            )

    result = (
        response.model_dump() if hasattr(response, "model_dump") else dict(response)
    )

    with open(path, "w") as handle:
        json.dump(result, handle, default=str)

    return result


def _json_from(text: str) -> dict[str, Any]:
    start, end = text.find("{"), text.rfind("}")

    if start < 0 or end <= start:
        raise ValueError("model did not return JSON")

    return json.loads(text[start : end + 1])


async def listen(workdir: str, wav_path: str, instructions: str) -> dict[str, Any]:
    """Ask an audio-capable model about a recording; returns its JSON answer."""
    import base64

    with open(wav_path, "rb") as handle:
        audio = handle.read()

    path = _cache(workdir, "listen:" + instructions + hashlib.sha1(audio).hexdigest())

    if os.path.isfile(path):
        with open(path) as handle:
            return json.load(handle)

    client = _client()
    last: Exception | None = None

    for model in [
        m
        for m in (
            os.environ.get("EARWITNESS_AUDIO_MODEL"),
            "gpt-audio-1.5",
            "gpt-audio",
        )
        if m
    ]:
        try:
            response = await client.chat.completions.create(
                model=model,
                modalities=["text"],
                messages=[
                    {"role": "system", "content": instructions},
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "text",
                                "text": "Analyse this recording. JSON only.",
                            },
                            {
                                "type": "input_audio",
                                "input_audio": {
                                    "data": base64.b64encode(audio).decode(),
                                    "format": "wav",
                                },
                            },
                        ],
                    },
                ],
            )
        except Exception as error:  # noqa: BLE001 - try the next model
            last = error

            continue

        result = _json_from(response.choices[0].message.content or "")
        result["_model"] = model

        with open(path, "w") as handle:
            json.dump(result, handle)

        return result

    raise RuntimeError(f"no audio model available: {last}")

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useCaseStream } from '../../lib/useCaseStream'
import { Playback, PlaybackContext } from '../../lib/playback'
import type { CaseState } from '../../lib/state'
import { isTerminal } from '../../lib/state'
import { api } from '../../lib/api'
import { mmss } from '../../lib/format'
import { deriveFacts, type Facts } from '../../lib/facts'
import { useHealth } from '../../lib/health'
import { modulePlain, VERDICT } from '../../lib/plain'
import { mockName } from '../../lib/mock'
import { Badge, Icon } from '../ui/ui'
import { Player } from './Player'
import { FindingsBoard } from './Findings'
import { GeoBoard, geoFinding } from './GeoBoard'
import { Reveal } from './Reveal'
import { Answers, Detail, EvidenceFile, Exhibits, exhibitItems, hasNotes, KeyMoments, MapSection, mapPoints, MethodSection, NotesSection } from './Sections'

export type SectionKey = 'findings' | 'exhibits' | 'geo' | 'map' | 'notes' | 'file' | 'method'
export const SECTIONS: SectionKey[] = ['findings', 'exhibits', 'geo', 'map', 'notes', 'file', 'method']

/** Old tab links keep working: they open the matching section. */
export function sectionFor(key: string | undefined): { section: SectionKey | null; topic?: string } {
  if (!key || key === 'overview') return { section: null }
  if ((SECTIONS as string[]).includes(key)) return { section: key as SectionKey }
  if (key === 'place') return { section: 'map', topic: 'place' }
  if (['timeline', 'sound', 'light', 'picture', 'people', 'text'].includes(key)) return { section: 'exhibits', topic: key }
  return { section: null }
}

export function CasePage({ caseId, section, onSection }: { caseId: string; section: string | undefined; onSection: (s: SectionKey | null) => void }) {
  const [nonce, setNonce] = useState(0)
  const { state, conn } = useCaseStream(caseId, nonce)
  const pb = useMemo(() => new Playback(), [])
  const { health } = useHealth()
  const facts = useMemo(() => deriveFacts(state, health?.openai ?? null), [state, health?.openai])
  const [open, setOpen] = useState<Set<SectionKey>>(new Set())
  const [focus, setFocus] = useState<string | null>(null)
  const info = state.info
  const points = useMemo(() => mapPoints(state, facts), [state, facts])
  const locationAnswered = facts.answers.some((a) => a.key === 'where' && a.confidence !== 'unknown') || !!facts.gps
  const [mapDefaulted, setMapDefaulted] = useState(false)
  const geo = geoFinding(state)
  const dossier = state.artifacts['brief:dossier'] ?? state.artifactOrder.map((id) => state.artifacts[id]).find((a) => a.kind === 'dossier') ?? null
  const [revealing, setRevealing] = useState(false)

  useEffect(() => {
    if (info?.duration_s) pb.set({ duration: info.duration_s })
  }, [pb, info?.duration_s])
  useEffect(() => {
    document.title = info ? `${VERDICT[facts.verdict].short} · ${info.filename} · EARWITNESS` : 'EARWITNESS'
  }, [info, facts.verdict])

  // The map opens by itself only when the case has a location answer.
  // The geolocation board opens by itself whenever there is a geo finding.
  useEffect(() => {
    if (mapDefaulted || facts.running) return
    if (geo) {
      setMapDefaulted(true)
      setOpen((o) => new Set(o).add('geo'))
    } else if (points.length) {
      setMapDefaulted(true)
      if (locationAnswered) setOpen((o) => new Set(o).add('map'))
    }
  }, [points.length, locationAnswered, facts.running, mapDefaulted, !!geo])

  // Deep link: #/case/{id}/{section} opens and scrolls to that item.
  useEffect(() => {
    if (!info) return
    const { section: s, topic } = sectionFor(section)
    const target = (s === 'map' || s === 'geo') && geo ? 'geo' : s === 'map' && !points.length ? 'exhibits' : s
    if (!target) return
    setOpen((o) => new Set(o).add(target))
    const t = setTimeout(() => {
      const el = (topic && document.getElementById(`topic-${topic}`)) || document.getElementById(`d-${target}`)
      el?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }, 60)
    return () => clearTimeout(t)
  }, [section, !!info, points.length, !!geo])

  const toggle = (s: SectionKey) =>
    setOpen((o) => {
      const n = new Set(o)
      if (n.has(s)) n.delete(s)
      else n.add(s)
      return n
    })

  const openFinding = useCallback(
    (id: string) => {
      setOpen((o) => new Set(o).add('findings'))
      setFocus(null)
      requestAnimationFrame(() => setFocus(id))
      onSection('findings')
    },
    [onSection],
  )

  const arts = state.artifactOrder.map((id) => state.artifacts[id])
  const ofKind = (k: string) => arts.filter((a) => a.kind === k)
  const exhibits = exhibitItems(state, !!geo)
  const notes = hasNotes(facts)

  return (
    <PlaybackContext.Provider value={pb}>
      <CaseHead
        state={state}
        facts={facts}
        caseId={caseId}
        onRerun={async () => {
          await api.rerun(caseId)
          setNonce((n) => n + 1)
        }}
      />
      <main className="wrap case-page">
        {state.error ? (
          <p className="verdict-line err-line">This case could not be opened: {state.error}</p>
        ) : !info ? (
          <div className="skeleton" aria-label="Loading the case">
            <span />
            <span />
            <span className="tall" />
          </div>
        ) : (
          <>
            <VerdictLine state={state} facts={facts} conn={conn} />
            {dossier && (
              <button className="reveal-btn" onClick={() => setRevealing(true)}>
                <Icon name="eye" /> What this video gives away
              </button>
            )}

            <section className="block">
              <div className="video-col">
                <div className="video-frame">
                  <Player
                    info={info}
                    mediaUrl={state.mediaUrl}
                    mediaReady={state.mediaReady}
                    running={facts.running}
                    heatmaps={ofKind('heatmap')}
                    captions={ofKind('captions')}
                    height={480}
                  />
                </div>
                <KeyMoments findings={state.findings} duration={info.duration_s} />
              </div>
            </section>

            <section className="block">
              <h2 className="block-title">What we found</h2>
              {facts.running && !facts.answers.length ? (
                <p className="muted">The answers are written once every check has finished.</p>
              ) : (
                <Answers state={state} facts={facts} openFinding={openFinding} />
              )}
            </section>

            <section className="block">
              <h2 className="block-title">Details</h2>
              <div className="details">
                <Detail
                  id="findings"
                  title="Every finding"
                  desc="Everything every check reported, most serious first, with all its measurements."
                  count={state.findings.length}
                  open={open.has('findings')}
                  onToggle={() => toggle('findings')}
                >
                  <FindingsBoard findings={state.findings} modules={state.modules} focus={focus} />
                </Detail>
                <Detail
                  id="exhibits"
                  title="Charts and exhibits"
                  desc="Spectrograms, charts, tamper maps and frames, grouped by topic, each with how to read it."
                  count={exhibits.length}
                  open={open.has('exhibits')}
                  onToggle={() => toggle('exhibits')}
                >
                  <Exhibits state={state} geoBoard={!!geo} />
                </Detail>
                {geo && (
                  <Detail
                    id="geo"
                    title="Where it was filmed"
                    desc="Places the AI proposed from the pixels and sounds, each checked against real-world photos and satellite views."
                    count={geo.data?.verified ? 'verified' : 'lead'}
                    open={open.has('geo')}
                    onToggle={() => toggle('geo')}
                  >
                    <GeoBoard state={state} facts={facts} points={points} />
                  </Detail>
                )}
                {!geo && points.length > 0 && (
                  <Detail
                    id="map"
                    title="Map"
                    desc={facts.gps ? 'The GPS position stored in the file, and any estimate from the picture.' : 'Where the picture suggests it was filmed.'}
                    count={points.length}
                    open={open.has('map')}
                    onToggle={() => toggle('map')}
                  >
                    <MapSection points={points} gps={facts.gps} />
                  </Detail>
                )}
                {notes && (
                  <Detail
                    id="notes"
                    title="Analyst’s note"
                    desc="The written assessment, with links to the findings it cites."
                    open={open.has('notes')}
                    onToggle={() => toggle('notes')}
                  >
                    <NotesSection facts={facts} openFinding={openFinding} />
                  </Detail>
                )}
                <Detail
                  id="file"
                  title="Evidence file"
                  desc="Fingerprints, file facts, tracks, every stored label and the raw technical readout."
                  open={open.has('file')}
                  onToggle={() => toggle('file')}
                >
                  <EvidenceFile state={state} facts={facts} caseId={caseId} />
                </Detail>
                <Detail
                  id="method"
                  title="How each check ran"
                  desc="Every check, what it does, its limits, status and timing, plus the activity log."
                  count={`${facts.checksDone}/${facts.checksTotal}`}
                  open={open.has('method')}
                  onToggle={() => toggle('method')}
                >
                  <MethodSection state={state} facts={facts} />
                </Detail>
              </div>
            </section>
          </>
        )}
      </main>
      {revealing && dossier && (
        <Reveal
          state={state}
          dossier={dossier}
          caseId={caseId}
          onClose={(jump) => {
            setRevealing(false)
            if (jump) openFinding(jump)
          }}
        />
      )}
    </PlaybackContext.Provider>
  )
}

function Seal({ facts }: { facts: Facts }) {
  const v = VERDICT[facts.verdict]
  return (
    <div className={`seal v-${facts.verdict}`} data-tip={v.line}>
      <span className="seal-icon">{facts.verdict === 'running' ? <i className="pulse-dot big" /> : <Icon name={v.icon} />}</span>
      <span className="seal-text">
        <b>{facts.verdict === 'running' ? 'Analysing' : v.word}</b>
        {facts.verdict === 'running' && (
          <small>
            {facts.checksDone} of {facts.checksTotal} checks
          </small>
        )}
      </span>
    </div>
  )
}

function CaseHead({ state, facts, caseId, onRerun }: { state: CaseState; facts: Facts; caseId: string; onRerun: () => void }) {
  const info = state.info
  return (
    <section className={`case-head v-${facts.verdict}`}>
      {info?.thumb_url && <div className="cover" style={{ backgroundImage: `url(${info.thumb_url})` }} />}
      <div className="cover-tint" />
      <div className="wrap head-top">
        {info?.thumb_url ? <img className="avatar" src={info.thumb_url} alt="" /> : <div className="avatar" />}
        <div className="who-block">
          <a href="#/" className="case-label mono" data-tip="Back to all cases">
            <Icon name="arrow-left" /> CASE {caseId}
          </a>
          <h1 className={`name v-${facts.verdict}`} title={info?.filename}>
            {info?.filename ?? 'Opening…'}
          </h1>
          {info && (
            <div className="badges">
              <Badge icon="mobile-screen" accent={facts.device ? 'blue' : 'grey'}>
                {facts.device ?? 'Unknown device'}
              </Badge>
              <Badge icon="clock" accent="teal">
                {mmss(info.duration_s)}
              </Badge>
              <Badge icon="location-dot" accent={facts.gps ? 'red' : 'grey'} tip={facts.gps ? 'The file stores its own GPS position' : 'No GPS position in the file'}>
                {facts.gps ? 'GPS in file' : 'No GPS'}
              </Badge>
            </div>
          )}
        </div>
        <div className="head-actions">
          <Seal facts={facts} />
          <div className="head-icons">
            <a className="icon-btn" href={api.reportUrl(caseId)} target="_blank" rel="noreferrer" data-tip="Printable report" aria-label="Report">
              <Icon name="file-lines" />
            </a>
            {!mockName() && (
              <button className="icon-btn" onClick={onRerun} disabled={facts.running} data-tip="Run every check again" aria-label="Rerun">
                <Icon name="rotate-right" />
              </button>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}

function VerdictLine({ state, facts, conn }: { state: CaseState; facts: Facts; conn: string }) {
  if (facts.running) {
    const m = facts.currentModule
    const phrase = m ? modulePlain(m, state.modules[m]?.title).does.split(/[.:]/)[0] : 'Opening the file'
    return (
      <section className="verdict-block">
        <p className="verdict-line">Examining this video…</p>
        <div className="run-line">
          <span className="muted">
            {phrase}… {facts.checksDone} of {facts.checksTotal} checks done
          </span>
          <div className="progress">
            <span style={{ width: `${facts.checksTotal ? (facts.checksDone / facts.checksTotal) * 100 : 0}%` }} />
          </div>
        </div>
      </section>
    )
  }
  const flagged = facts.counts.critical + facts.counts.warning
  const flaggedModules = new Set(state.findings.filter((f) => f.severity === 'critical' || f.severity === 'warning').map((f) => f.module))
  const passed = state.moduleOrder.filter((n) => state.modules[n]?.status === 'done' && !flaggedModules.has(n)).length
  const unfinished = state.moduleOrder.filter((n) => !isTerminal(state.modules[n]?.status ?? 'queued')).length
  return (
    <section className="verdict-block">
      <p className={`verdict-line v-${facts.verdict}`}>{facts.summary ?? VERDICT[facts.verdict].line}</p>
      <p className="muted">
        {flagged} {flagged === 1 ? 'thing' : 'things'} worth checking · {passed} {passed === 1 ? 'check' : 'checks'} passed
        {unfinished && conn !== 'live' ? ` · ${unfinished} unfinished` : ''}
      </p>
    </section>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import type { Artifact, CaseInfo } from '../../lib/types'
import { useIsPlaying, usePlayback, usePlayhead } from '../../lib/playback'
import { useElementSize } from '../../lib/hooks'
import { mmss } from '../../lib/format'
import { capture } from '../../lib/pointer'
import { Icon } from '../ui/ui'
import { EnhanceModal, type EnhanceBox } from './EnhanceModal'
import { segmentsOf } from '../viz/Transcript'

interface Rect {
  x: number
  y: number
  w: number
  h: number
}

/** Where the picture sits inside an object-fit:contain element (letterboxing). */
function contentRect(boxW: number, boxH: number, vw: number, vh: number): Rect {
  if (!vw || !vh || !boxW || !boxH) return { x: 0, y: 0, w: boxW, h: boxH }
  const s = Math.min(boxW / vw, boxH / vh)
  return { x: (boxW - vw * s) / 2, y: (boxH - vh * s) / 2, w: vw * s, h: vh * s }
}

export function Player({
  info,
  mediaUrl,
  mediaReady,
  running,
  heatmaps,
  captions,
  height = 420,
  compact,
}: {
  info: CaseInfo | null
  mediaUrl: string | null
  mediaReady: boolean
  running: boolean
  heatmaps: Artifact[]
  captions: Artifact[]
  height?: number
  compact?: boolean
}) {
  const pb = usePlayback()
  const playing = useIsPlaying()
  const t = usePlayhead()
  const videoRef = useRef<HTMLVideoElement>(null)
  const [stageRef, stage] = useElementSize<HTMLDivElement>()
  const [natural, setNatural] = useState({ w: 0, h: 0 })
  const [rate, setRate] = useState(1)
  const [muted, setMuted] = useState(true)
  const [enhanceMode, setEnhanceMode] = useState(false)
  const [drag, setDrag] = useState<{ x0: number; y0: number; x1: number; y1: number } | null>(null)
  const [request, setRequest] = useState<EnhanceBox | null>(null)
  const [overlayOn, setOverlayOn] = useState(false)
  const [ccOn, setCcOn] = useState(true)

  const fps = info?.video?.fps || 30
  const vw = natural.w || info?.video?.width || 16
  const vh = natural.h || info?.video?.height || 9
  const rect = contentRect(stage.width, stage.height, vw, vh)
  const hasVideo = !!mediaUrl

  useEffect(() => {
    const v = videoRef.current
    if (!v) return
    pb.attach((time) => {
      v.currentTime = time
    })
    let raf = 0
    const loop = () => {
      pb.set({ time: v.currentTime })
      if (!v.paused) raf = requestAnimationFrame(loop)
    }
    const onPlay = () => {
      pb.set({ playing: true })
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(loop)
    }
    const onPause = () => {
      cancelAnimationFrame(raf)
      pb.set({ playing: false, time: v.currentTime })
    }
    const onSeeked = () => pb.set({ time: v.currentTime })
    const onMeta = () => {
      setNatural({ w: v.videoWidth, h: v.videoHeight })
      if (isFinite(v.duration) && v.duration > 0) pb.set({ duration: Math.max(pb.duration, v.duration) })
      // the player can remount when switching tabs: resume where we were
      if (pb.time > 0 && Math.abs(v.currentTime - pb.time) > 0.05) v.currentTime = pb.time
    }
    v.addEventListener('play', onPlay)
    v.addEventListener('pause', onPause)
    v.addEventListener('ended', onPause)
    v.addEventListener('seeked', onSeeked)
    v.addEventListener('timeupdate', onSeeked)
    v.addEventListener('loadedmetadata', onMeta)
    return () => {
      cancelAnimationFrame(raf)
      pb.attach(null)
      pb.set({ playing: false })
      v.removeEventListener('play', onPlay)
      v.removeEventListener('pause', onPause)
      v.removeEventListener('ended', onPause)
      v.removeEventListener('seeked', onSeeked)
      v.removeEventListener('timeupdate', onSeeked)
      v.removeEventListener('loadedmetadata', onMeta)
    }
  }, [pb, mediaUrl])

  useEffect(() => {
    if (videoRef.current) videoRef.current.playbackRate = rate
  }, [rate, mediaUrl])

  const toggle = () => {
    const v = videoRef.current
    if (!v) return
    if (v.paused) {
      setEnhanceMode(false)
      v.play().catch(() => undefined)
    } else v.pause()
  }
  const step = (frames: number) => {
    const v = videoRef.current
    if (!v) return
    v.pause()
    pb.seek(v.currentTime + frames / fps)
  }
  const startEnhance = () => {
    videoRef.current?.pause()
    setEnhanceMode((m) => !m)
    setDrag(null)
  }

  useEffect(() => {
    const on = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT' || el.isContentEditable)) return
      if (e.metaKey || e.ctrlKey || e.altKey) return
      if (e.key === ' ') {
        e.preventDefault()
        toggle()
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault()
        step(e.shiftKey ? -10 : -1)
      } else if (e.key === 'ArrowRight') {
        e.preventDefault()
        step(e.shiftKey ? 10 : 1)
      } else if ((e.key === 'z' || e.key === 'Z') && hasVideo) startEnhance()
      else if (e.key === 'Escape') setEnhanceMode(false)
    }
    window.addEventListener('keydown', on)
    return () => window.removeEventListener('keydown', on)
  })

  const local = (e: React.PointerEvent) => {
    const b = (e.currentTarget as HTMLElement).getBoundingClientRect()
    return {
      x: Math.min(rect.x + rect.w, Math.max(rect.x, e.clientX - b.left)),
      y: Math.min(rect.y + rect.h, Math.max(rect.y, e.clientY - b.top)),
    }
  }
  const sel = drag && { x: Math.min(drag.x0, drag.x1), y: Math.min(drag.y0, drag.y1), w: Math.abs(drag.x1 - drag.x0), h: Math.abs(drag.y1 - drag.y0) }
  const finishDrag = () => {
    if (!sel || sel.w < 6 || sel.h < 6 || !rect.w || !rect.h) return setDrag(null)
    setRequest({
      x: (sel.x - rect.x) / rect.w,
      y: (sel.y - rect.y) / rect.h,
      w: sel.w / rect.w,
      h: sel.h / rect.h,
      time_s: videoRef.current?.currentTime ?? pb.time,
    })
    setDrag(null)
    setEnhanceMode(false)
  }

  const heat = useMemo(() => {
    if (!overlayOn) return null
    let best: Artifact | null = null
    let bestD = Infinity
    for (const a of heatmaps) {
      if (!a.url || a.data?.overlay === false) continue
      const at = a.data?.time_s ?? a.time_s
      const d = at == null ? 0.75 : Math.abs(at - t)
      if (d < bestD) {
        best = a
        bestD = d
      }
    }
    return bestD <= 1.5 ? best : null
  }, [heatmaps, t, overlayOn])

  const subtitle = useMemo(() => {
    if (!ccOn) return null
    for (const c of captions) for (const s of segmentsOf(c)) if (t >= s.start && t < s.end) return s.text
    return null
  }, [captions, t, ccOn])

  return (
    <div className={`player ${compact ? 'compact' : ''}`}>
      <div className="stage" ref={stageRef} style={{ height }}>
        {hasVideo ? (
          <video ref={videoRef} src={mediaUrl!} poster={info?.thumb_url ?? undefined} playsInline muted={muted} preload="auto" onClick={toggle} />
        ) : (
          info?.thumb_url && <img className="poster" src={info.thumb_url} alt="" />
        )}
        {heat && <img className="heat" src={heat.url!} alt="" style={{ left: rect.x, top: rect.y, width: rect.w, height: rect.h }} />}
        {subtitle && (
          <div className="subtitle" style={{ left: rect.x, width: rect.w, top: rect.y + rect.h - 56 }}>
            <span>{subtitle}</span>
          </div>
        )}
        <div className="stage-tag">
          {running && (
            <span className="live">
              <i className="pulse-dot" /> ANALYSING
            </span>
          )}
        </div>
        <div className="stage-tc mono">
          {mmss(t)} <span className="faint">/ {mmss(pb.duration || info?.duration_s)}</span>
          {!compact && hasVideo && <span className="faint"> · frame {Math.round(t * fps)}</span>}
        </div>
        {!hasVideo && <div className="stage-msg">{mediaReady ? 'This video cannot be played in the browser.' : 'Preparing a playable copy…'}</div>}
        {heat && <div className="stage-msg top">Overlay: {heat.title}</div>}

        {enhanceMode && (
          <div
            className="enhance-layer"
            onPointerDown={(e) => {
              capture(e)
              const p = local(e)
              setDrag({ x0: p.x, y0: p.y, x1: p.x, y1: p.y })
            }}
            onPointerMove={(e) => {
              if (!drag) return
              const p = local(e)
              setDrag({ ...drag, x1: p.x, y1: p.y })
            }}
            onPointerUp={finishDrag}
          >
            <div className="content-box" style={{ left: rect.x, top: rect.y, width: rect.w, height: rect.h }} />
            {sel && sel.w > 0 && (
              <div className="sel" style={{ left: sel.x, top: sel.y, width: sel.w, height: sel.h }}>
                <span className="mono">
                  {Math.round((sel.w / rect.w) * vw)}×{Math.round((sel.h / rect.h) * vh)} px
                </span>
              </div>
            )}
            {!sel && <div className="enhance-hint">Drag a box around the detail you want to see (Esc to cancel)</div>}
          </div>
        )}
      </div>

      <div className="controls">
        <button className="ctl" onClick={() => step(-1)} disabled={!hasVideo} data-tip="Back one frame (←)" aria-label="Back one frame">
          <Icon name="backward-step" />
        </button>
        <button className="ctl play" onClick={toggle} disabled={!hasVideo} data-tip="Play / pause (space)" aria-label={playing ? 'Pause' : 'Play'}>
          <Icon name={playing ? 'pause' : 'play'} />
        </button>
        <button className="ctl" onClick={() => step(1)} disabled={!hasVideo} data-tip="Forward one frame (→)" aria-label="Forward one frame">
          <Icon name="forward-step" />
        </button>
        {!compact &&
          [0.25, 0.5, 1].map((r) => (
            <button key={r} className={`ctl txt ${rate === r ? 'on' : ''}`} onClick={() => setRate(r)} disabled={!hasVideo} data-tip="Playback speed">
              {r}×
            </button>
          ))}
        <button className="ctl" onClick={() => setMuted((m) => !m)} disabled={!hasVideo || !info?.has_audio} data-tip={muted ? 'Turn sound on' : 'Mute'} aria-label="Sound">
          <Icon name={muted ? 'volume-xmark' : 'volume-high'} />
        </button>
        {captions.length > 0 && (
          <button className={`ctl ${ccOn ? 'on' : ''}`} onClick={() => setCcOn((c) => !c)} data-tip="Subtitles from the speech transcript" aria-label="Subtitles">
            <Icon name="closed-captioning" />
          </button>
        )}
        {heatmaps.length > 0 && (
          <button className={`ctl ${overlayOn ? 'on' : ''}`} onClick={() => setOverlayOn((o) => !o)} data-tip="Overlay the nearest tamper map on the video" aria-label="Tamper overlay">
            <Icon name="layer-group" />
          </button>
        )}
        <span className="grow" />
        <button className={`btn btn-red sm ${enhanceMode ? 'on' : ''}`} onClick={startEnhance} disabled={!hasVideo} data-tip="Stack nearby frames to sharpen a region (Z)">
          <Icon name="magnifying-glass-plus" /> {compact ? 'Zoom' : 'Zoom in on a detail'}
        </button>
      </div>

      {request && info && <EnhanceModal caseId={info.id} box={request} onClose={() => setRequest(null)} />}
    </div>
  )
}

import { Fragment, useMemo, useState, type ReactNode } from 'react'
