import { artifactTab, BULLET_LABEL, CONFIDENCE, GLOSSARY, modulePlain, SEVERITY, TABS, type TabKey } from '../../lib/plain'
import { CopyButton, Icon, SevChip, SourceChip, Term } from '../ui/ui'
import { DataView, JsonTree } from '../ui/Data'
