/* enhance */
.enh-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-bottom: 14px;
  padding-right: 40px;
}
.enh-head h3 {
  font-size: 18px;
}
.enh-head .tabs {
  margin-left: auto;
}
.enh-wait {
  position: relative;
  height: 400px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 14px;
  overflow: hidden;
  border-radius: 6px;
  background: #0b0b0b;
}
.enh-wait .big {
  font-size: 34px;
}
.enh-title {
  font-size: 26px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
.enh-scan {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 0%, rgb(219 40 40 / 0.12) 48%, rgb(219 40 40 / 0.5) 50%, transparent 51%);
  background-size: 100% 200%;
  animation: scan 1.8s linear infinite;
}
@keyframes scan {
  from { background-position: 0 100%; }
  to { background-position: 0 -100%; }
}
.compare {
  position: relative;
  height: min(60vh, 620px);
  overflow: hidden;
  border-radius: 6px;
  background: #000;
  cursor: ew-resize;
  user-select: none;
}
.compare img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.compare .handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  margin-left: -1px;
  background: var(--red);
}
.compare .handle span {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--red);
  transform: translate(-50%, -50%);
}
.compare .tag {
  position: absolute;
  top: 10px;
  padding: 2px 9px;
  border-radius: 4px;
  background: rgb(0 0 0 / 0.75);
  color: #e6e6e6;
  font-size: 12px;
}
.compare .tag.l { left: 10px; }
.compare .tag.r { right: 10px; color: var(--red-t); }
.side-by-side {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.side-by-side figure {
  margin: 0;
  background: #000;
  border-radius: 6px;
  overflow: hidden;
}
.side-by-side img {
  width: 100%;
  height: min(56vh, 580px);
  object-fit: contain;
}
.side-by-side figcaption {
  padding: 6px 10px;
  font-size: 13px;
  background: var(--panel-2);
}

